-- Демонстрационный набор полигонов Московской области: наполнение, а не схема.
--
-- Зачем. В наборе два полигона, и экран сравнения с двумя строками ничего не
-- сравнивает: порядок по цене и отбор по расстоянию проверяются вхолостую
-- (R-023, R-024, R-025). Восемь полигонов разнесены по области — от Мытищ до
-- Волоколамска, — чтобы граница «до 50 км» делила список, а не отсекала его.

-- Названия, координаты и вид объекта — открытые данные OpenStreetMap,
-- выгружены через Overpass API (https://overpass-api.de/api/interpreter)
-- 24.09.2026: объекты landuse=landfill и amenity=recycling с
-- recycling_type=centre, у которых заполнено name. Муниципальный округ в
-- адресе получен обратным геокодированием Nominatim того же дня
-- (https://nominatim.openstreetmap.org). Данные распространяются по лицензии
-- ODbL 1.0 (https://opendatacommons.org/licenses/odbl/), которая требует
-- указания источника, © участники OpenStreetMap.

-- Тарифы утилизации и статусы приёма — демонстрационные, источника у них нет.
-- Открытого перечня цен утилизации не существует, поэтому величины назначены
-- однородно с начальным набором (0002_demo_dataset.sql) и для боевой работы
-- подлежат замене из официального перечня; цены — вопрос Q-001. Основание
-- есть ровно у одного статуса: OpenStreetMap называет «Кучино» закрытым.

-- Юрлицо, суточный лимит и учёт в АИС ОССиГ оставлены пустыми намеренно:
-- открытый источник их не даёт, а выдуманное юрлицо — не пробел, а ложь.
-- Так же заведена «Икша» начального набора.

-- Плечи перевозки — ответы открытой службы маршрутизации OSRM
-- (https://router.project-osrm.org, профиль driving, служебная матрица table),
-- получены 24.09.2026: 307 адресов справочника на 8 полигонов, 2456 строк.
-- Расстояние по прямой сюда не кладётся — оно занижает стоимость перевозки,
-- и отказ лучше заниженной сметы (R-020).

-- Повторное применение безвредно: on conflict do nothing оставляет уже
-- изменённые записи как есть.
--
-- @req: R-020, R-040, R-044


-- Полигоны (R-040, R-044). Идентификатор объекта OpenStreetMap указан
-- рядом с каждой строкой: по нему запись сверяется с источником.
insert into landfill (
    id, name, legal_entity, address, latitude, longitude,
    object_kind, registered_in_ais_ossig, status, status_reason,
    status_source, status_updated_at
) values
